"""Columnar execution engine.

The scanner reads each CSV table in record batches of at most
:data:`BATCH_SIZE` rows, materializing only the columns referenced by the
SELECT list, the GROUP BY key or the WHERE clause (column pruning).
Within a batch the predicate — an AND/OR/parentheses boolean tree of
column-op-value comparisons — is evaluated column-at-a-time *before*
projection or grouping (predicate pushdown), and aggregates — either a
single global row or per-group hash tables keyed by one GROUP BY column
or a tuple of several GROUP BY columns — roll forward batch by batch.
HAVING, when present, is evaluated only after the aggregates have been
exactly computed: it drops the global row or individual groups, never
individual input rows.

ORDER BY, when present, sorts the surviving result rows — after WHERE,
aggregation and HAVING — by one or more SELECT result columns, each with
its own ASC (default) or DESC direction. Finite-decimal values compare by
exact numeric value (``1`` equals ``1.0``); everything else compares by
raw text, never coerced to a number. Multi-item keys compare left to
right; rows equal on every key keep their incoming order (CSV row order
for projections, first-appearance order for groups). LIMIT, when present,
truncates the sorted rows last.

Every cell read by a numeric comparison is parsed eagerly for every row
of a batch, even on rows whose other OR branches already settle the
outcome: OR never short-circuits cell validation, so a non-numeric cell
anywhere a numeric predicate reaches fails the whole query.

All arithmetic and numeric comparison go through :class:`decimal.Decimal`
so results are deterministic and free of binary-float artifacts.
"""

from __future__ import annotations

import csv
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any, Dict, List, Sequence, Tuple

from .sql import (
    Comparison,
    HavingComparison,
    HavingExpr,
    Query,
    SelectItem,
    SortItem,
    WhereExpr,
    parse_sql,
)

BATCH_SIZE = 1024


def _decimal(field: str, column: str) -> Decimal:
    try:
        value = Decimal(field)
    except (InvalidOperation, ValueError):
        raise ValueError(
            f"column {column!r} contains non-numeric value {field!r}"
        )
    if not value.is_finite():
        raise ValueError(
            f"column {column!r} contains non-numeric value {field!r}"
        )
    return value


def _compare(left: Any, op: str, right: Any) -> bool:
    if op == "=":
        return left == right
    if op == "!=":
        return left != right
    if op == ">":
        return left > right
    if op == ">=":
        return left >= right
    if op == "<":
        return left < right
    return left <= right  # "<="


def _column_vector(rows: Sequence[Sequence[str]], idx: int) -> List[str]:
    """Extract one column from a row batch; short rows yield empty fields."""
    vec: List[str] = []
    for row in rows:
        vec.append(row[idx] if idx < len(row) else "")
    return vec


def _comparison_vector(
    rows: Sequence[Sequence[str]],
    col_index: Dict[str, int],
    comp: Comparison,
) -> List[bool]:
    """Evaluate one comparison over every row of the batch.

    The column is parsed for *every* row up front, including rows whose
    other OR branches already decide the row: OR does not short-circuit
    cell validation.
    """
    idx = col_index[comp.column]
    vec = _column_vector(rows, idx)
    result: List[bool] = [False] * len(vec)
    if comp.quoted:
        target_text = comp.value_text
        for i, field in enumerate(vec):
            result[i] = _compare(field, comp.op, target_text)
    else:
        target = Decimal(comp.value_text)
        for i, field in enumerate(vec):
            result[i] = _compare(_decimal(field, comp.column), comp.op, target)
    return result


def _combine(op: str, vectors: Sequence[Sequence[bool]]) -> List[bool]:
    """Combine per-row boolean vectors with AND or OR."""
    if op == "AND":
        mask = [True] * len(vectors[0])
        for vec in vectors:
            for i, value in enumerate(vec):
                mask[i] = mask[i] and value
        return mask
    mask = [False] * len(vectors[0])
    for vec in vectors:
        for i, value in enumerate(vec):
            mask[i] = mask[i] or value
    return mask


def _eval_node(
    node: WhereExpr,
    rows: Sequence[Sequence[str]],
    col_index: Dict[str, int],
) -> List[bool]:
    """Vectorized boolean-tree evaluation on raw columns."""
    if isinstance(node, Comparison):
        return _comparison_vector(rows, col_index, node)
    vectors = [_eval_node(operand, rows, col_index) for operand in node.operands]
    return _combine(node.op, vectors)


def _evaluate_predicate(
    rows: List[Sequence[str]],
    col_index: Dict[str, int],
    where: WhereExpr,
) -> List[bool]:
    """Vectorized predicate tree; runs on raw columns, ahead of projection."""
    return _eval_node(where, rows, col_index)


def _eval_having(
    node: HavingExpr, count: int, sums: Dict[str, Decimal]
) -> bool:
    """Evaluate a HAVING tree against one fully computed aggregate row.

    Left operands are always numeric (an integer row count or an exactly
    summed Decimal); textual aggregate results are never coerced, and the
    right operands are the parser-validated finite decimal literals.
    """
    if isinstance(node, HavingComparison):
        if node.kind == "count_star":
            left: Decimal = Decimal(count)
        else:
            left = sums[node.column]
        return _compare(left, node.op, Decimal(node.value_text))
    if node.op == "AND":
        return all(_eval_having(operand, count, sums) for operand in node.operands)
    return any(_eval_having(operand, count, sums) for operand in node.operands)


def _project_value(field: str) -> Any:
    """Infer a projected cell: decimal-able text becomes a JSON number."""
    try:
        value = Decimal(field)
    except (InvalidOperation, ValueError):
        return field
    if not value.is_finite():
        return field
    if value == value.to_integral_value():
        return int(value)
    return value


def _number(value: Decimal) -> Any:
    """Render an aggregate sum as int when integral, else keep Decimal."""
    if value == value.to_integral_value():
        return int(value)
    return value


def _group_key(field: str) -> Any:
    """Normalize a grouping cell.

    Finite decimal text groups by exact decimal value (so ``1`` and
    ``1.0`` share a group); everything else groups by raw text.
    """
    try:
        value = Decimal(field)
    except (InvalidOperation, ValueError):
        return field
    if not value.is_finite():
        return field
    return value


def _key_output(key: Any) -> Any:
    """Render a grouping key for JSON: numeric keys follow projection rules."""
    if isinstance(key, Decimal):
        return _number(key)
    return key


def _aggregate_result(query: Query, count: int, sums: Dict[str, Decimal]) -> Dict[str, Any]:
    row: List[Any] = []
    for item in query.select:
        if item.kind == "count_star":
            row.append(count)
        else:
            row.append(_number(sums[item.column]))
    return {
        "columns": [item.text for item in query.select],
        "rows": [row],
        "row_count": 1,
    }


def _grouped_result(
    query: Query,
    order: List[Tuple[Any, ...]],
    counts: Dict[Tuple[Any, ...], int],
    sums: Dict[Tuple[Any, ...], Dict[str, Decimal]],
) -> Dict[str, Any]:
    group_cols = query.group_by
    rows: List[List[Any]] = []
    for key in order:
        row: List[Any] = []
        for pos, item in enumerate(query.select):
            if pos < len(group_cols):
                # The leading SELECT items are the GROUP BY columns, in order.
                row.append(_key_output(key[pos]))
            elif item.kind == "count_star":
                row.append(counts[key])
            else:
                row.append(_number(sums[key][item.column]))
        rows.append(row)
    return {
        "columns": [item.text for item in query.select],
        "rows": rows,
        "row_count": len(rows),
    }


def _sort_key(value: Any) -> Tuple[int, Any]:
    """Order key for one result cell.

    Finite decimals (already int/Decimal after projection, key rendering or
    aggregation) compare by exact numeric value, so ``1`` and ``1.0`` tie;
    everything else compares by raw text and is never coerced to a number.
    Numbers order before text so mixed columns stay deterministic.
    """
    if isinstance(value, (int, Decimal)) and not isinstance(value, bool):
        return (0, Decimal(value))
    return (1, str(value))


def _apply_order_by(
    result: Dict[str, Any],
    order_by: Tuple[SortItem, ...],
    select: Tuple[SelectItem, ...],
) -> None:
    """Sort result rows in place, one stable pass per item, last item first.

    Each sort item was validated against the SELECT list at parse time, so
    its column position always resolves. Stability keeps rows that tie on
    every key in their incoming order (CSV row order for projections,
    first-appearance order for groups).
    """
    rows = result["rows"]
    for item in reversed(order_by):
        idx = next(
            pos
            for pos, si in enumerate(select)
            if si.kind == item.kind and si.column == item.column
        )
        rows.sort(key=lambda row, i=idx: _sort_key(row[i]), reverse=item.descending)


def _apply_limit(result: Dict[str, Any], limit: int) -> None:
    """Truncate result rows in place; LIMIT 0 keeps columns, empties rows."""
    del result["rows"][limit:]
    result["row_count"] = len(result["rows"])


def _run_batches(
    reader: csv.reader,
    query: Query,
    header: Sequence[str],
) -> Dict[str, Any]:
    col_index = {name: header.index(name) for name in query.required_columns()}

    projected_rows: List[List[Any]] = []
    count = 0
    sums: Dict[str, Decimal] = {
        item.column: Decimal(0)
        for item in query.select
        if item.kind == "sum"
    }
    select_cols: Tuple[SelectItem, ...] = query.select

    if query.is_grouped:
        # First-appearance order of composite group keys over the
        # filtered row stream.
        order: List[Tuple[Any, ...]] = []
        group_counts: Dict[Tuple[Any, ...], int] = {}
        group_sums: Dict[Tuple[Any, ...], Dict[str, Decimal]] = {}
        group_idxs = [col_index[name] for name in query.group_by]
        sum_items = [item for item in select_cols if item.kind == "sum"]

        while True:
            batch = [row for _, row in zip(range(BATCH_SIZE), reader)]
            if not batch:
                break
            mask = (
                [True] * len(batch)
                if query.where is None
                else _evaluate_predicate(batch, col_index, query.where)
            )
            for i, matched in enumerate(mask):
                if not matched:
                    continue
                row = batch[i]
                key = tuple(
                    _group_key(row[idx] if idx < len(row) else "")
                    for idx in group_idxs
                )
                if key not in group_counts:
                    group_counts[key] = 0
                    group_sums[key] = {item.column: Decimal(0) for item in sum_items}
                    order.append(key)
                group_counts[key] += 1
                for item in sum_items:
                    idx = col_index[item.column]
                    sum_field = row[idx] if idx < len(row) else ""
                    group_sums[key][item.column] += _decimal(sum_field, item.column)

        if query.having is not None:
            # HAVING runs after every group has been exactly computed and
            # only drops whole groups; first-appearance order is preserved.
            order = [
                key
                for key in order
                if _eval_having(query.having, group_counts[key], group_sums[key])
            ]
        return _grouped_result(query, order, group_counts, group_sums)

    while True:
        batch = [row for _, row in zip(range(BATCH_SIZE), reader)]
        if not batch:
            break
        mask = (
            [True] * len(batch)
            if query.where is None
            else _evaluate_predicate(batch, col_index, query.where)
        )

        if query.is_aggregate:
            for i, matched in enumerate(mask):
                if not matched:
                    continue
                count += 1
                row = batch[i]
                for item in select_cols:
                    if item.kind == "sum":
                        field = row[col_index[item.column]] if col_index[item.column] < len(row) else ""
                        sums[item.column] += _decimal(field, item.column)
        else:
            indices = [col_index[item.column] for item in select_cols]
            for i, matched in enumerate(mask):
                if not matched:
                    continue
                row = batch[i]
                projected_rows.append(
                    [
                        _project_value(row[idx] if idx < len(row) else "")
                        for idx in indices
                    ]
                )

    if query.is_aggregate:
        result = _aggregate_result(query, count, sums)
        if query.having is not None and not _eval_having(
            query.having, count, sums
        ):
            # A global aggregate always computes one row; HAVING failing
            # leaves the same columns but no rows.
            result["rows"] = []
            result["row_count"] = 0
        return result
    return {
        "columns": [item.text for item in select_cols],
        "rows": projected_rows,
        "row_count": len(projected_rows),
    }


def _dumps(obj: Any) -> str:
    """Deterministic JSON encoder; Decimal values render as decimal numbers."""

    def encode(value: Any) -> str:
        if value is None:
            return "null"
        if value is True:
            return "true"
        if isinstance(value, bool):
            return "false"
        if isinstance(value, Decimal):
            return format(value, "f")
        if isinstance(value, int):
            return str(value)
        if isinstance(value, str):
            return _json_string(value)
        if isinstance(value, list):
            return "[" + ",".join(encode(v) for v in value) + "]"
        if isinstance(value, dict):
            return (
                "{"
                + ",".join(
                    f"{_json_string(k)}:{encode(v)}" for k, v in value.items()
                )
                + "}"
            )
        raise TypeError(f"cannot serialize {type(value).__name__}")

    return encode(obj)


def _json_string(text: str) -> str:
    out = ['"']
    for ch in text:
        if ch == '"':
            out.append('\\"')
        elif ch == "\\":
            out.append("\\\\")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif ord(ch) < 0x20:
            out.append(f"\\u{ord(ch):04x}")
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)


def execute(data_dir: str, sql: str) -> Dict[str, Any]:
    """Run *sql* against CSV tables in *data_dir*; return a result dict.

    Raises:
        FileNotFoundError: the table's CSV file does not exist.
        KeyError: the query references a column absent from the header.
        ValueError: the SQL is malformed/unsupported, or a required field
            cannot be read as a decimal number.
    """
    query: Query = parse_sql(sql)
    table_path = Path(data_dir) / f"{query.table}.csv"
    # Built-in open raises FileNotFoundError, preserving the required type.
    with open(table_path, "r", encoding="utf-8", newline="") as fh:
        reader = csv.reader(fh)
        try:
            header = next(reader)
        except StopIteration:
            header = []
        for name in query.required_columns():
            if name not in header:
                raise KeyError(
                    f"column {name!r} does not exist in table {query.table!r}"
                )
        result = _run_batches(reader, query, header)
        # ORDER BY sorts the fully computed result rows; LIMIT truncates last.
        if query.order_by:
            _apply_order_by(result, query.order_by, query.select)
        if query.limit is not None:
            _apply_limit(result, query.limit)
        return result


def render(result: Dict[str, Any]) -> str:
    """Serialize a query result as a single JSON object."""
    return _dumps(result)

"""Minimal self-contained SQL lexer and parser.

Supported grammar (the complete surface for this baseline)::

    query      := SELECT select_list FROM identifier
                  [ WHERE boolean ] [ GROUP BY identifier (, identifier)* ]
                  [ HAVING having_boolean ]
                  [ ORDER BY sort_item (, sort_item)* ] [ LIMIT integer ]
    sort_item  := (identifier | count_star | sum_expr) [ ASC | DESC ]
    select_list:= grouping_column (, grouping_column)*,
                  count_star, sum_expr (, sum_expr)*   (grouped aggregate query)
                | count_star [, sum_expr ]*            (aggregate query)
                | column (, column)*                   (projection query)
    boolean    := or_expr
    or_expr    := and_expr (OR and_expr)*
    and_expr   := factor (AND factor)*
    factor     := LPAREN or_expr RPAREN | comparison
    comparison := identifier op value
    op         := = | != | > | >= | < | <=
    value      := number-literal | double-quoted-string-literal

HAVING shares the AND/OR/parentheses boolean shape, but its leaves are
aggregate-to-number comparisons::

    having_boolean := having_or
    having_factor  := LPAREN having_or RPAREN | having_comparison
    having_comparison := aggregate op number-literal
    aggregate      := count_star | sum_expr

The left side must be a ``count(*)`` or ``sum(column)`` expression that
already appears in the SELECT list; the right side is an unquoted finite
decimal literal only (no strings, no columns, no other expressions).

AND binds tighter than OR; parentheses may be nested to override the
precedence. Parentheses *combine* boolean conditions only: a parenthesized
group must itself contain an AND/OR combination (``(a = 1)`` is rejected),
and parentheses may never wrap columns, values or comparisons-as-values.
There is no NOT, no constant truth value and no other expression forms.

HAVING may appear at most once and only after GROUP BY (or after WHERE in
an ungrouped aggregate query); it is rejected on plain projection queries.

ORDER BY follows HAVING (or WHERE/GROUP BY when HAVING is absent) and LIMIT
follows ORDER BY; each may appear at most once and never out of order. Each
sort item references a result column already in the SELECT list — a plain or
grouping column, ``count(*)`` or ``sum(column)`` — with an optional ``ASC``
(default) or ``DESC`` direction; duplicate sort items and references to
expressions absent from the SELECT list are rejected. LIMIT takes a single
non-negative decimal integer literal (digits only: no sign, no fraction, no
strings, columns or expressions).

A grouped query names one or more distinct grouping columns (at least two
for the multi-column shape): they must head the SELECT list in the same
order as the GROUP BY list, followed by count(*) and one or more distinct
sum(column) expressions.

Anything else (missing FROM, NOT, functions other than count(*)/sum() in
SELECT, wildcards, extra clauses, malformed syntax, unmatched parentheses,
OR outside WHERE/HAVING) raises :class:`ValueError`.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import List, Optional, Tuple, Union


class _TokKind(Enum):
    IDENT = "ident"
    KEYWORD = "keyword"
    NUMBER = "number"
    STRING = "string"
    OP = "op"
    COMMA = "comma"
    STAR = "star"
    LPAREN = "lparen"
    RPAREN = "rparen"
    EOF = "eof"


_KEYWORDS = {
    "SELECT", "FROM", "WHERE", "AND", "OR", "NOT", "GROUP", "BY", "HAVING",
    "ORDER", "LIMIT",
}


@dataclass
class _Token:
    kind: _TokKind
    text: str


def _tokenize(sql: str) -> List[_Token]:
    tokens: List[_Token] = []
    i, n = 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        if c == ",":
            tokens.append(_Token(_TokKind.COMMA, c))
            i += 1
            continue
        if c == "(":
            tokens.append(_Token(_TokKind.LPAREN, c))
            i += 1
            continue
        if c == ")":
            tokens.append(_Token(_TokKind.RPAREN, c))
            i += 1
            continue
        if c == "*":
            tokens.append(_Token(_TokKind.STAR, c))
            i += 1
            continue
        if c == '"':
            j = i + 1
            buf: List[str] = []
            while j < n and sql[j] != '"':
                buf.append(sql[j])
                j += 1
            if j >= n:
                raise ValueError("unterminated string literal in query")
            tokens.append(_Token(_TokKind.STRING, "".join(buf)))
            i = j + 1
            continue
        if c in "=<>":
            if i + 1 < n and sql[i + 1] == "=":
                tokens.append(_Token(_TokKind.OP, c + "="))
                i += 2
            else:
                tokens.append(_Token(_TokKind.OP, c))
                i += 1
            continue
        if c == "!":
            if i + 1 < n and sql[i + 1] == "=":
                tokens.append(_Token(_TokKind.OP, "!="))
                i += 2
                continue
            raise ValueError(f"unexpected character '!' at position {i}")
        if c.isdigit() or (c == "-" and i + 1 < n and sql[i + 1].isdigit()):
            j = i + 1
            while j < n and (sql[j].isdigit() or sql[j] == "."):
                j += 1
            text = sql[i:j]
            # Reject malformed numbers such as "1.2.3".
            _parse_decimal(text)
            tokens.append(_Token(_TokKind.NUMBER, text))
            i = j
            continue
        if c.isalpha() or c == "_":
            j = i + 1
            while j < n and (sql[j].isalnum() or sql[j] == "_"):
                j += 1
            text = sql[i:j]
            upper = text.upper()
            kind = _TokKind.KEYWORD if upper in _KEYWORDS else _TokKind.IDENT
            tokens.append(_Token(kind, upper if kind is _TokKind.KEYWORD else text))
            i = j
            continue
        raise ValueError(f"unexpected character {c!r} at position {i}")
    tokens.append(_Token(_TokKind.EOF, ""))
    return tokens


def _parse_decimal(text: str):
    """Validate a decimal numeric literal; return a Decimal-like float-free value."""
    from decimal import Decimal, InvalidOperation

    try:
        return Decimal(text)
    except InvalidOperation:
        raise ValueError(f"invalid numeric literal {text!r}")


@dataclass(frozen=True)
class Comparison:
    column: str
    op: str
    # value_text is the raw literal; quoted distinguishes text vs numeric.
    value_text: str
    quoted: bool


@dataclass(frozen=True)
class BoolOp:
    """A conjunction or disjunction of boolean conditions.

    ``op`` is ``"AND"`` or ``"OR"``; operands are leaf comparisons
    (:class:`Comparison` for WHERE, :class:`HavingComparison` for HAVING)
    or further :class:`BoolOp` nodes.
    """

    op: str
    operands: Tuple["BooleanNode", ...]


WhereExpr = Union[Comparison, BoolOp]


@dataclass(frozen=True)
class HavingComparison:
    """One HAVING leaf: aggregate op finite-decimal-literal.

    ``kind`` is ``"count_star"`` or ``"sum"`` (with ``column`` naming the
    summed column); ``text`` is the aggregate's SELECT expression text.
    """

    text: str
    kind: str
    op: str
    value_text: str
    column: Optional[str] = None


HavingExpr = Union[HavingComparison, BoolOp]

BooleanNode = Union[Comparison, HavingComparison, BoolOp]


@dataclass(frozen=True)
class SelectItem:
    # Original expression text as written in the query, e.g. "count(*)", "sum(a)".
    text: str
    kind: str  # "column" | "count_star" | "sum"
    column: Optional[str] = None


@dataclass(frozen=True)
class SortItem:
    """One ORDER BY item: a result-column reference with a direction.

    ``text`` is the normalized expression text (``a``, ``count(*)``,
    ``sum(a)``); ``kind``/``column`` mirror :class:`SelectItem`.
    """

    text: str
    kind: str  # "column" | "count_star" | "sum"
    column: Optional[str] = None
    descending: bool = False


@dataclass(frozen=True)
class Query:
    select: Tuple[SelectItem, ...]
    table: str
    where: Optional[WhereExpr] = None
    group_by: Tuple[str, ...] = ()
    having: Optional[HavingExpr] = None
    order_by: Tuple[SortItem, ...] = ()
    limit: Optional[int] = None

    @property
    def is_aggregate(self) -> bool:
        return bool(self.group_by) or self.select[0].kind == "count_star"

    @property
    def is_grouped(self) -> bool:
        return bool(self.group_by)

    def required_columns(self) -> Tuple[str, ...]:
        """Columns the scan must materialize (group key, sums, predicates)."""
        cols: List[str] = []
        seen = set()
        for item in self.select:
            if item.kind == "column":
                if item.column not in seen:
                    seen.add(item.column)
                    cols.append(item.column)
            elif item.kind == "sum" and item.column not in seen:
                seen.add(item.column)
                cols.append(item.column)
        if self.where is not None:
            self._collect_where_columns(self.where, cols, seen)
        return tuple(cols)

    @staticmethod
    def _collect_where_columns(
        node: WhereExpr, cols: List[str], seen: set
    ) -> None:
        if isinstance(node, Comparison):
            if node.column not in seen:
                seen.add(node.column)
                cols.append(node.column)
            return
        for operand in node.operands:
            Query._collect_where_columns(operand, cols, seen)


_OPS = {"=", "!=", ">", ">=", "<", "<="}


class _Parser:
    def __init__(self, sql: str):
        self.tokens = _tokenize(sql)
        self.pos = 0

    def _peek(self) -> _Token:
        return self.tokens[self.pos]

    def _next(self) -> _Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def _expect_keyword(self, word: str) -> None:
        tok = self._next()
        if tok.kind is not _TokKind.KEYWORD or tok.text != word:
            raise ValueError(f"expected {word} but found {tok.text!r}")

    def _accept_keyword(self, word: str) -> bool:
        tok = self._peek()
        if tok.kind is _TokKind.KEYWORD and tok.text == word:
            self._next()
            return True
        return False

    def parse(self) -> Query:
        self._expect_keyword("SELECT")
        items = self._parse_select_list()
        self._expect_keyword("FROM")
        table_tok = self._next()
        if table_tok.kind is not _TokKind.IDENT:
            raise ValueError("table name must be a simple identifier")
        where: Optional[WhereExpr] = None
        having: Optional[HavingExpr] = None
        group_by: List[str] = []
        order_by: List[SortItem] = []
        limit: Optional[int] = None
        tok = self._peek()
        if tok.kind is _TokKind.KEYWORD and tok.text == "WHERE":
            self._next()
            where = self._parse_or()
            tok = self._peek()
        if tok.kind is _TokKind.KEYWORD and tok.text == "GROUP":
            self._next()
            self._expect_keyword("BY")
            group_by = [self._expect(_TokKind.IDENT).text]
            while self._peek().kind is _TokKind.COMMA:
                self._next()
                group_by.append(self._expect(_TokKind.IDENT).text)
            self._validate_grouped(items, group_by)
            tok = self._peek()
        else:
            self._validate_ungrouped(items)
        if tok.kind is _TokKind.KEYWORD and tok.text == "HAVING":
            self._next()
            having = self._parse_having_or()
            if not (bool(group_by) or items[0].kind == "count_star"):
                raise ValueError("HAVING is only valid on aggregate queries")
            self._validate_having_aggregates(having, items)
            tok = self._peek()
        if tok.kind is _TokKind.KEYWORD and tok.text == "ORDER":
            self._next()
            self._expect_keyword("BY")
            order_by = [self._parse_sort_item(items)]
            while self._peek().kind is _TokKind.COMMA:
                self._next()
                order_by.append(self._parse_sort_item(items))
            seen_items = set()
            for sort_item in order_by:
                key = (sort_item.kind, sort_item.column)
                if key in seen_items:
                    raise ValueError(
                        f"duplicate ORDER BY item {sort_item.text!r}"
                    )
                seen_items.add(key)
            tok = self._peek()
        if tok.kind is _TokKind.KEYWORD and tok.text == "LIMIT":
            self._next()
            limit = self._parse_limit()
            tok = self._peek()
        if tok.kind is not _TokKind.EOF:
            # Trailing tokens: an unsupported clause, a second ORDER BY or
            # LIMIT, a clause out of order, an unmatched ')' or plain
            # malformed input.
            raise ValueError(f"unsupported or unexpected token {tok.text!r}")
        return Query(
            tuple(items),
            table_tok.text,
            where,
            tuple(group_by),
            having,
            tuple(order_by),
            limit,
        )

    def _validate_grouped(
        self, items: List[SelectItem], group_by: List[str]
    ) -> None:
        """Enforce the grouped shape.

        SELECT leads with the GROUP BY columns in the same order (distinct),
        followed by count(*) and one or more distinct sum(column) items.
        """
        if len(group_by) != len(set(group_by)):
            raise ValueError("GROUP BY may not list the same column twice")
        if len(items) < len(group_by) + 2:
            raise ValueError(
                "grouped SELECT must list the grouping columns followed by "
                "count(*) and one or more sum(column)"
            )
        for pos, group_col in enumerate(group_by):
            item = items[pos]
            if item.kind != "column" or item.column != group_col:
                raise ValueError(
                    "SELECT grouping columns must lead the SELECT list in "
                    "the same order as GROUP BY"
                )
        if items[len(group_by)].kind != "count_star":
            raise ValueError(
                "grouped SELECT must list count(*) after the grouping columns"
            )
        seen_sums = set()
        for item in items[len(group_by) + 1 :]:
            if item.kind != "sum":
                raise ValueError(
                    "grouped SELECT may only contain the grouping columns, "
                    "count(*) and sum(column)"
                )
            if item.column in seen_sums:
                raise ValueError(f"duplicate aggregate sum({item.column})")
            if item.column in group_by:
                raise ValueError(
                    f"GROUP BY column {item.column} may not be summed"
                )
            seen_sums.add(item.column)

    def _parse_select_list(self) -> List[SelectItem]:
        items = [self._parse_select_item()]
        while self._peek().kind is _TokKind.COMMA:
            self._next()
            items.append(self._parse_select_item())
        return items

    def _validate_ungrouped(self, items: List[SelectItem]) -> None:
        """Rules for queries without GROUP BY (the baseline shapes)."""
        if items[0].kind == "sum":
            raise ValueError("sum(column) requires count(*) in the SELECT list")
        aggregate = items[0].kind == "count_star"
        for item in items[1:]:
            if aggregate:
                if item.kind != "sum":
                    raise ValueError(
                        "aggregate SELECT may only contain count(*) and sum(column)"
                    )
            elif item.kind == "sum":
                raise ValueError(
                    "sum(column) requires count(*) in the SELECT list"
                )
            elif item.kind != "column":
                raise ValueError(
                    "count(*)/sum() cannot be mixed with plain columns"
                )

    def _parse_select_item(self) -> SelectItem:
        tok = self._peek()
        # function form: ident '(' ... ')'
        if tok.kind is _TokKind.IDENT and self.tokens[self.pos + 1].kind is _TokKind.LPAREN:
            name_tok = self._next()
            self._next()  # (
            inner = self._next()
            self._expect(_TokKind.RPAREN)
            upper = name_tok.text.upper()
            if upper == "COUNT" and inner.kind is _TokKind.STAR:
                return SelectItem("count(*)", "count_star")
            if upper == "SUM" and inner.kind is _TokKind.IDENT:
                return SelectItem(f"sum({inner.text})", "sum", inner.text)
            # Any other function (count(col), avg, max, ...) is unsupported.
            raise ValueError(
                f"unsupported SELECT expression {name_tok.text}({inner.text})"
            )
        if tok.kind is _TokKind.STAR:
            raise ValueError("wildcard column '*' is not supported")
        if tok.kind is _TokKind.IDENT:
            self._next()
            return SelectItem(tok.text, "column", tok.text)
        raise ValueError(f"invalid SELECT item {tok.text!r}")

    def _expect(self, kind: _TokKind) -> _Token:
        tok = self._next()
        if tok.kind is not kind:
            raise ValueError(f"expected {kind.value} but found {tok.text!r}")
        return tok

    # ----- WHERE boolean grammar: or_expr := and_expr (OR and_expr)* -----

    def _parse_or(self) -> WhereExpr:
        operands = [self._parse_and()]
        while self._accept_keyword("OR"):
            operands.append(self._parse_and())
        if len(operands) == 1:
            return operands[0]
        return BoolOp("OR", tuple(operands))

    def _parse_and(self) -> WhereExpr:
        operands = [self._parse_factor()]
        while self._accept_keyword("AND"):
            operands.append(self._parse_factor())
        if len(operands) == 1:
            return operands[0]
        return BoolOp("AND", tuple(operands))

    def _parse_factor(self) -> WhereExpr:
        tok = self._peek()
        if tok.kind is _TokKind.LPAREN:
            self._next()
            node = self._parse_or()
            self._expect(_TokKind.RPAREN)
            if isinstance(node, Comparison):
                # Parentheses only *combine* boolean conditions; they may
                # not wrap a single comparison, a column or a value.
                raise ValueError(
                    "parentheses may only group combined AND/OR conditions, "
                    "not a single comparison"
                )
            return node
        if tok.kind is _TokKind.IDENT:
            return self._parse_comparison()
        # NOT, dangling AND/OR, ')', EOF, numbers, ...: none can start a
        # boolean condition.
        raise ValueError(f"expected a boolean condition but found {tok.text!r}")

    def _parse_comparison(self) -> Comparison:
        col = self._expect(_TokKind.IDENT)
        op_tok = self._expect(_TokKind.OP)
        if op_tok.text not in _OPS:
            raise ValueError(f"unsupported operator {op_tok.text!r}")
        val = self._next()
        if val.kind is _TokKind.NUMBER:
            return Comparison(col.text, op_tok.text, val.text, False)
        if val.kind is _TokKind.STRING:
            return Comparison(col.text, op_tok.text, val.text, True)
        raise ValueError(
            "comparison value must be an unquoted number or a double-quoted string"
        )

    # ----- HAVING boolean grammar: aggregate op number, AND/OR/parens -----

    def _parse_having_or(self) -> HavingExpr:
        operands = [self._parse_having_and()]
        while self._accept_keyword("OR"):
            operands.append(self._parse_having_and())
        if len(operands) == 1:
            return operands[0]
        return BoolOp("OR", tuple(operands))

    def _parse_having_and(self) -> HavingExpr:
        operands = [self._parse_having_factor()]
        while self._accept_keyword("AND"):
            operands.append(self._parse_having_factor())
        if len(operands) == 1:
            return operands[0]
        return BoolOp("AND", tuple(operands))

    def _parse_having_factor(self) -> HavingExpr:
        tok = self._peek()
        if tok.kind is _TokKind.LPAREN:
            self._next()
            node = self._parse_having_or()
            self._expect(_TokKind.RPAREN)
            if isinstance(node, HavingComparison):
                # As in WHERE, parentheses only combine conditions; they
                # may not wrap a single HAVING comparison.
                raise ValueError(
                    "parentheses may only group combined AND/OR conditions, "
                    "not a single comparison"
                )
            return node
        if (
            tok.kind is _TokKind.IDENT
            and self.tokens[self.pos + 1].kind is _TokKind.LPAREN
        ):
            return self._parse_having_comparison()
        # Plain columns/grouping columns, NOT, numbers, dangling AND/OR,
        # ')', EOF, ...: none can start a HAVING aggregate comparison.
        raise ValueError(
            "HAVING condition must compare count(*) or sum(column) with a "
            f"number, but found {tok.text!r}"
        )

    def _parse_having_comparison(self) -> HavingComparison:
        name_tok = self._next()  # the aggregate identifier
        self._next()  # LPAREN
        inner = self._next()
        self._expect(_TokKind.RPAREN)
        upper = name_tok.text.upper()
        if upper == "COUNT" and inner.kind is _TokKind.STAR:
            text, kind, column = "count(*)", "count_star", None
        elif upper == "SUM" and inner.kind is _TokKind.IDENT:
            text, kind, column = f"sum({inner.text})", "sum", inner.text
        else:
            raise ValueError(
                "HAVING may only compare count(*) or sum(column) aggregates"
            )
        op_tok = self._expect(_TokKind.OP)
        if op_tok.text not in _OPS:
            raise ValueError(f"unsupported operator {op_tok.text!r}")
        val = self._next()
        if val.kind is not _TokKind.NUMBER:
            # Quoted strings, columns, aggregates, keywords, EOF: HAVING
            # compares aggregates against finite decimal literals only.
            raise ValueError(
                "HAVING comparison value must be an unquoted finite decimal number"
            )
        return HavingComparison(text, kind, op_tok.text, val.text, column)

    def _validate_having_aggregates(
        self, node: HavingExpr, items: List[SelectItem]
    ) -> None:
        """Every HAVING aggregate must already appear in the SELECT list."""
        if isinstance(node, BoolOp):
            for operand in node.operands:
                self._validate_having_aggregates(operand, items)
            return
        for item in items:
            if node.kind == "count_star" and item.kind == "count_star":
                return
            if (
                node.kind == "sum"
                and item.kind == "sum"
                and item.column == node.column
            ):
                return
        raise ValueError(
            f"HAVING aggregate {node.text} is not in the SELECT list"
        )

    # ----- ORDER BY / LIMIT -----

    def _parse_sort_item(self, items: List[SelectItem]) -> SortItem:
        tok = self._peek()
        if (
            tok.kind is _TokKind.IDENT
            and self.tokens[self.pos + 1].kind is _TokKind.LPAREN
        ):
            name_tok = self._next()
            self._next()  # (
            inner = self._next()
            self._expect(_TokKind.RPAREN)
            upper = name_tok.text.upper()
            if upper == "COUNT" and inner.kind is _TokKind.STAR:
                text, kind, column = "count(*)", "count_star", None
            elif upper == "SUM" and inner.kind is _TokKind.IDENT:
                text, kind, column = f"sum({inner.text})", "sum", inner.text
            else:
                raise ValueError(
                    "ORDER BY may only reference result columns, count(*) "
                    "or sum(column)"
                )
        elif tok.kind is _TokKind.IDENT:
            self._next()
            text, kind, column = tok.text, "column", tok.text
        else:
            # Numbers, strings, keywords, '*', parens, EOF: none can start
            # a sort item.
            raise ValueError(f"invalid ORDER BY item {tok.text!r}")
        # ASC/DESC are contextual: they stay plain identifiers so a column
        # named e.g. "asc" remains usable elsewhere in the grammar.
        descending = False
        nxt = self._peek()
        if nxt.kind is _TokKind.IDENT and nxt.text.upper() in ("ASC", "DESC"):
            self._next()
            descending = nxt.text.upper() == "DESC"
        sort_item = SortItem(text, kind, column, descending)
        self._validate_sort_item(sort_item, items)
        return sort_item

    def _validate_sort_item(
        self, sort_item: SortItem, items: List[SelectItem]
    ) -> None:
        """Every ORDER BY item must reference a column of the result."""
        for item in items:
            if item.kind == sort_item.kind and item.column == sort_item.column:
                return
        if sort_item.kind == "column":
            raise ValueError(
                f"ORDER BY column {sort_item.text!r} is not in the SELECT list"
            )
        raise ValueError(
            f"ORDER BY aggregate {sort_item.text} is not in the SELECT list"
        )

    def _parse_limit(self) -> int:
        tok = self._next()
        if (
            tok.kind is not _TokKind.NUMBER
            or not tok.text.isascii()
            or not tok.text.isdigit()
        ):
            # Negatives, fractions, strings, columns, expressions, missing
            # values: LIMIT takes digits only.
            raise ValueError(
                "LIMIT must be followed by a non-negative decimal integer"
            )
        return int(tok.text)


def parse_sql(sql: str) -> Query:
    """Parse a query string into a :class:`Query`."""
    if not isinstance(sql, str) or not sql.strip():
        raise ValueError("empty query")
    return _Parser(sql).parse()

